package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.persistence.mapper.RuntimeRetentionMapper;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real services/schema/subject guard, with stateful durable-boundary doubles. No NOT_FOUND cancellation. */
public class RuntimeRetentionCancellationTest extends RuntimeRetentionAuthorFixture {
 final Map<String,RuntimeRetentionMapper.Cancellation> cancelled=new HashMap<>();
 final RuntimeRetentionCancellation cancellation=new RuntimeRetentionCancellation(access,mapper,permissions,resources,authority,schema,json);
 public RuntimeRetentionCancellationTest()throws Exception{super();
  when(mapper.cancellationByKey(anyMap())).thenAnswer(i->cancelled.values().stream().filter(r->r.createdBy().equals(map(i).get("userId"))&&r.cancelKey().equals(map(i).get("key"))).toList());
  when(mapper.cancellationByOriginal(anyMap())).thenAnswer(i->cancelled.values().stream().filter(r->r.createdBy().equals(map(i).get("userId"))&&r.originalKind().equals(map(i).get("originalKind"))&&r.originalKey().equals(map(i).get("originalKey"))).toList());
  when(mapper.cancellationOperation(anyMap())).thenAnswer(i->optional(operations.get(map(i).get("operationId"))));when(mapper.cancellationAudit(anyMap())).thenAnswer(i->optional(audits.get(map(i).get("auditId"))));when(mapper.cancellationEvent(anyMap())).thenAnswer(i->optional(events.get(map(i).get("eventId"))));
  when(mapper.insertCancelOperation(anyMap())).thenAnswer(i->{var v=map(i);operations.put(str(v,"operationId"),str(v,"receiptJson"));return 1;});
  when(mapper.insertCancellation(anyMap())).thenAnswer(i->{var v=map(i);var r=new RuntimeRetentionMapper.Cancellation(id(1),str(v,"projectId"),str(v,"cancellationId"),str(v,"fixedJson"),str(v,"contentHash"),str(v,"operationId"),str(v,"key"),str(v,"originalKind"),str(v,"originalKey"),str(v,"originalHash"),str(v,"userId"),time(v),str(v,"classification"),"1.0.0",str(v,"manifest"));cancelled.put(r.cancellationId(),r);return 1;});
 }
 ObjectNode input(String kind,String key,JsonNode original){var q=json.object().put("schema_version","1.0.0").put("original_kind",kind).put("original_key",key);q.set("original_request",original.deepCopy());return q;}
 @Test void cancelBeforeApproveBlocksEveryLateOriginalAndAlteredBody()throws Exception{within(()->{var q=input("APPROVE","cancelled-approve-key",request);var r=cancellation.cancel(actor,"1","cancel-command-key",bytes(q));assertEquals("CANCELLED",r.path("status").asText());assertTrue(r.path("receipt").isNull());assertEquals(r,cancellation.cancel(actor,"1","cancel-command-key",bytes(q)));assertEquals(r,cancellation.recover(actor,"1","cancel-command-key").required("receipt"));assertThrows(TenantAccessException.class,()->service.approve(actor,"1","cancelled-approve-key",bytes(request)));request.put("reason","changed request");assertThrows(TenantAccessException.class,()->service.approve(actor,"1","cancelled-approve-key",bytes(request)));verify(mapper,never()).insertPolicy(anyMap());});}
 @Test void approveFirstReturnsExactOriginalAndDoesNotUndoPolicy()throws Exception{within(()->{var original=service.approve(actor,"1","already-approved-key",bytes(request));var r=cancellation.cancel(actor,"1","cancel-completed-key",bytes(input("APPROVE","already-approved-key",request)));assertEquals("COMPLETED",r.path("status").asText());assertEquals(original,r.required("receipt"));assertEquals(original,service.approve(actor,"1","already-approved-key",bytes(request)));assertEquals("1",states.get(original.required("policy_revision").asText()).revision());});}
 @Test void cancelRetirementPreventsStateMutation()throws Exception{within(()->{var q=retirementRequest();var r=cancellation.cancel(actor,"1","cancel-retirement-command",bytes(input("RETIRE","cancelled-retire-key",q)));assertEquals("CANCELLED",r.path("status").asText());assertThrows(TenantAccessException.class,()->retirement.retire(actor,"1","cancelled-retire-key",bytes(q)));assertEquals("1",states.get(id(4)).revision());verify(mapper,never()).retireState(anyMap());});}
 @Test void retiredFirstReturnsRealRetirement()throws Exception{within(()->{var q=retirementRequest();var original=retirement.retire(actor,"1","completed-retire-key",bytes(q));var r=cancellation.cancel(actor,"1","cancel-completed-retire",bytes(input("RETIRE","completed-retire-key",q)));assertEquals("COMPLETED",r.path("status").asText());assertEquals(original,r.required("receipt"));assertEquals("2",states.get(id(4)).revision());});}
 @Test void cancellationNeedsReadButNeverApproval()throws Exception{within(()->{when(resources.require(eq(a),any(),eq("retention.approve"),anyString())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));var r=cancellation.cancel(actor,"1","read-only-cancel-key",bytes(input("APPROVE","read-only-original-key",request)));assertEquals("CANCELLED",r.path("status").asText());verify(resources,never()).require(eq(a),any(),eq("retention.approve"),anyString());});}
 @Test void noReadAndStaleContextCannotCreateTombstone()throws Exception{within(()->{var q=input("APPROVE","denied-original-key",request);assertThrows(TenantAccessException.class,()->cancellation.cancel(actor,"2","denied-cancel-key",bytes(q)));when(resources.require(eq(a),any(),eq("retention.read"),anyString())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->cancellation.cancel(actor,"1","denied-cancel-key",bytes(q)));assertTrue(cancelled.isEmpty());});}
 @Test void changedCancelBodyOrKeyDoesNotRewriteProof()throws Exception{within(()->{var q=input("APPROVE","conflict-original-key",request);cancellation.cancel(actor,"1","conflict-cancel-key",bytes(q));((ObjectNode)q.required("original_request")).put("reason","different");assertThrows(TenantAccessException.class,()->cancellation.cancel(actor,"1","conflict-cancel-key",bytes(q)));assertThrows(TenantAccessException.class,()->cancellation.cancel(actor,"1","another-cancel-key",bytes(q)));assertEquals(1,cancelled.size());});}
 @Test void editedPrivateWitnessWithRehashedRowFailsIndependentAudit()throws Exception{within(()->{cancellation.cancel(actor,"1","witness-cancel-key",bytes(input("APPROVE","witness-original-key",request)));var r=cancelled.values().iterator().next();var f=(ObjectNode)schema.read(r.fixedJson());f.put("session_id","forged-session");cancelled.put(r.cancellationId(),new RuntimeRetentionMapper.Cancellation(r.tenantId(),r.projectId(),r.cancellationId(),schema.canonical(f),schema.hash(f),r.operationId(),r.cancelKey(),r.originalKind(),r.originalKey(),r.originalHash(),r.createdBy(),r.createdAt(),r.classification(),r.schemaVersion(),r.manifest()));assertThrows(TenantAccessException.class,()->cancellation.recover(actor,"1","witness-cancel-key"));assertThrows(TenantAccessException.class,()->service.approve(actor,"1","witness-original-key",bytes(request)));});}
 @Test void notFoundNeverCreatesCancellationAndActorCannotRecoverAnother()throws Exception{within(()->{assertEquals("NOT_FOUND",cancellation.recover(actor,"1","absent-cancel-key").path("status").asText());assertTrue(cancelled.isEmpty());cancellation.cancel(actor,"1","private-cancel-key",bytes(input("APPROVE","private-original-key",request)));when(a.actorId()).thenReturn(id(99));assertEquals("NOT_FOUND",cancellation.recover(actor,"1","private-cancel-key").path("status").asText());});}
 @Test void everyCancellationMapperCallUsesActualSubjectGuard()throws Exception{within(()->{var guarded=(RuntimeRetentionMapper)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{RuntimeRetentionMapper.class},(proxy,method,args)->{TenantScope.requireSubjectParameter("com.ruoyi.medical.persistence.mapper.RuntimeRetentionMapper."+method.getName(),args[0]);try{return method.invoke(mapper,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});var c=new RuntimeRetentionCancellation(access,guarded,permissions,resources,authority,schema,json);c.cancel(actor,"1","guarded-cancel-key",bytes(input("APPROVE","guarded-original-key",request)));c.recover(actor,"1","guarded-cancel-key");});}
 @Test void completedCancellationCannotRecreateMissingApproval()throws Exception{within(()->{var original=service.approve(actor,"1","missing-approved-key",bytes(request));cancellation.cancel(actor,"1","missing-cancel-key",bytes(input("APPROVE","missing-approved-key",request)));policies.remove(original.required("policy_revision").asText());clearInvocations(mapper);assertThrows(TenantAccessException.class,()->service.approve(actor,"1","missing-approved-key",bytes(request)));verify(mapper,never()).insertPolicy(anyMap());});}
 @Test void completedCancellationCannotRecreateMissingRetirement()throws Exception{within(()->{var q=retirementRequest();var original=retirement.retire(actor,"1","missing-retired-key",bytes(q));cancellation.cancel(actor,"1","missing-retire-cancel",bytes(input("RETIRE","missing-retired-key",q)));decisions.remove(original.required("decision_id").asText());clearInvocations(mapper);assertThrows(TenantAccessException.class,()->retirement.retire(actor,"1","missing-retired-key",bytes(q)));verify(mapper,never()).insertRetirement(anyMap());});}
 @Test void completedCancellationRejectsDifferentReceiptWithSameBodyHash()throws Exception{within(()->{var original=service.approve(actor,"1","changed-receipt-key",bytes(request));cancellation.cancel(actor,"1","changed-receipt-cancel",bytes(input("APPROVE","changed-receipt-key",request)));var r=policies.get(original.required("policy_revision").asText());var forged=(ObjectNode)schema.read(r.receiptJson());forged.put("operation_id",id(99));policies.put(r.policyRevision(),new RuntimeRetentionMapper.Row(r.tenantId(),r.projectId(),r.policyRevision(),r.fixedJson(),r.requestJson(),r.requestHash(),r.contentHash(),r.operationId(),r.key(),r.creator(),r.createdAt(),r.classification(),r.schemaVersion(),r.manifest(),r.auditId(),r.eventId(),schema.canonical(forged),r.sessionId(),r.contextJson()));clearInvocations(mapper);assertThrows(TenantAccessException.class,()->service.approve(actor,"1","changed-receipt-key",bytes(request)));verify(mapper,never()).insertPolicy(anyMap());});}
 public static void main(String[]args)throws Exception{int n=0;for(var m:RuntimeRetentionCancellationTest.class.getDeclaredMethods())if(m.isAnnotationPresent(Test.class)){try{m.invoke(new RuntimeRetentionCancellationTest());System.out.println("PASS "+m.getName());n++;}catch(java.lang.reflect.InvocationTargetException e){throw new RuntimeException(m.getName(),e.getCause());}}System.out.println("PASS "+n+" cancellation tests");}
}
